package pe.edu.pucp.oceanlink;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.math.*;
@WebServlet("/ConsultaDetalleServlet")
public class ConsultaDetalleServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{
  try{long id=Entrada.id(r,"id");Segmento seg=new SegmentoDAO().buscar(id);if(seg==null){s.sendError(404);return;}String area="sup".equals(r.getSession().getAttribute("areaDemo"))?"sup":"no".equals(r.getParameter("area"))?"no":"cp";r.setAttribute("menu",area);r.setAttribute("rol",area.equals("sup")?"Supervisor":area.equals("no")?"Operador de red":"Planificador de capacidad");r.setAttribute("titulo",area.equals("no")?"Estado del segmento":"Detalle de capacidad");r.setAttribute("etiquetas",Etiquetas.todas());r.setAttribute("registro",seg);
   var servicios=new MantenimientoDAO().afectados(0,id);BigDecimal usada=servicios.stream().map(f->new BigDecimal(f[2])).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal ocupada;try(Connection c=Conexion.abrir()){ocupada=CapacidadDAO.ocupada(c,id,0,0);}r.setAttribute("usada",usada.stripTrailingZeros().toPlainString());r.setAttribute("reservada",ocupada.subtract(usada).stripTrailingZeros().toPlainString());r.setAttribute("disponible",seg.getCapacidad().subtract(ocupada).stripTrailingZeros().toPlainString());r.setAttribute("porcentaje",usada.multiply(BigDecimal.valueOf(100)).divide(seg.getCapacidad(),1,RoundingMode.HALF_UP));r.setAttribute("servicios",servicios);r.setAttribute("historial",DetalleDAO.filas("SELECT DATE_FORMAT(fecha,'%d/%m/%Y %H:%i'),capacidad_total_tbps,capacidad_utilizada_tbps,capacidad_reservada_tbps FROM historial_capacidad_segmento WHERE id_segmento=? ORDER BY fecha DESC",id));r.getRequestDispatcher("/WEB-INF/views/capacidadDetalle.jsp").forward(r,s);
  }catch(SQLException|IllegalArgumentException e){log("Error en detalle de capacidad",e);s.sendError(400,"No se pudo consultar el segmento.");}
 }
}
